def min_interval_brute(intervals, queries):
    result = []
    for q in queries:
        best = -1
        for l, r in intervals:                        # scan every interval, every query
            if l <= q <= r:
                size = r - l + 1
                if best == -1 or size < best:
                    best = size
        result.append(best)
    return result

