vector<int> minIntervalBrute(vector<vector<int>>& intervals, vector<int>& queries) {
    vector<int> result;
    for (int q : queries) {
        int best = -1;
        for (auto& iv : intervals) {                          // scan every interval, every query
            if (iv[0] <= q && q <= iv[1]) {
                int size = iv[1] - iv[0] + 1;
                if (best == -1 || size < best) best = size;
            }
        }
        result.push_back(best);
    }
    return result;
