import java.util.*;

public class Main {
    static int[] minInterval(int[][] intervals, int[] queries) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        int m = queries.length;
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> queries[a] - queries[b]);
        int[] result = new int[m];
        Arrays.fill(result, -1);
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);   // (size, right)
        int i = 0, n = intervals.length;
        for (int qi : order) {
            int q = queries[qi];
            while (i < n && intervals[i][0] <= q) {                       // sweep in newly eligible
                int l = intervals[i][0], r = intervals[i][1];
                heap.offer(new int[]{r - l + 1, r});
                i++;
            }
            while (!heap.isEmpty() && heap.peek()[1] < q) heap.poll();        // discard expired
            if (!heap.isEmpty()) result[qi] = heap.peek()[0];
        }
        return result;
    }
}

