#include <bits/stdc++.h>
using namespace std;

vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
    sort(intervals.begin(), intervals.end());
    int m = queries.size();
    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return queries[a] < queries[b]; });
    vector<int> result(m, -1);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> heap;    // (size, right)
    int i = 0, n = intervals.size();
    for (int qi : order) {
        int q = queries[qi];
        while (i < n && intervals[i][0] <= q) {                          // sweep in newly eligible
            int l = intervals[i][0], r = intervals[i][1];
            heap.push({r - l + 1, r});
            i++;
        }
        while (!heap.empty() && heap.top().second < q) heap.pop();           // discard expired
        if (!heap.empty()) result[qi] = heap.top().first;
    }
    return result;
}
